"""The JSON-RPC framing, against a real pipe and no Docker (plan D21, T1.5).

`McpSession` drives the wire by hand rather than through the `mcp` client library, because the
suite has to observe what the wire actually carries — `structuredContent`, `nextCursor`, and a
gated-off tool answering with a *successful* result that has `isError: true` (D20). Hand-rolled
framing has to be pinned: the shipped server logs to stderr and may emit notifications at any
time, so "the next line is my answer" is wrong and would only fail against a real container.

The stub is a real subprocess, so the reader threads, the blocking reads and the newline
framing are the real ones — only the container is gone.
"""

from __future__ import annotations

import subprocess
import sys
from collections.abc import Iterator
from pathlib import Path

import pytest
from harness.docker_util import ProbeError
from harness.mcp_session import McpSession

STUB = Path(__file__).parent / "stubs" / "fake_mcp_server.py"


@pytest.fixture
def session() -> Iterator[McpSession]:
    proc = subprocess.Popen(
        [sys.executable, str(STUB)],
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        bufsize=1,
    )
    started = McpSession(proc)
    try:
        yield started
    finally:
        started.close()


def test_initialize_reads_past_noise_and_foreign_replies(session: McpSession) -> None:
    reply = session.initialize()
    assert reply["result"]["serverInfo"]["name"] == "stub"


def test_one_session_answers_several_calls_in_order(session: McpSession) -> None:
    """The property the container reuse rests on: one process, many calls, no crosstalk."""
    session.initialize()
    for index in range(3):
        result = session.call("echo", {"n": index})
        assert result.text == f'{{"n": {index}}}'


def test_a_call_carries_content_and_structured_content(session: McpSession) -> None:
    session.initialize()
    result = session.call("echo", {"a": 1})

    assert result.structured == {"result": {"a": 1}}
    assert result.text == '{"a": 1}', "only text parts join into .text"
    assert len(result.content) == 2, "the raw content list stays intact for the assertions"
    assert result.raw["structuredContent"] == result.structured


def test_a_tool_error_is_reported_not_raised(session: McpSession) -> None:
    """D20: a refusal is a *successful* result with isError — raising would hide it."""
    session.initialize()
    result = session.call("boom")

    assert result.is_error is True
    assert result.text == "it blew up"


def test_a_json_rpc_error_raises(session: McpSession) -> None:
    """A protocol-level error is not a tool answer, so it must not look like one."""
    session.initialize()
    with pytest.raises(ProbeError, match="rpcfail"):
        session.call("rpcfail")


def test_a_silent_tool_times_out_and_shows_the_stderr_tail(session: McpSession) -> None:
    """Without the tail, a hung call reports a bare timeout and the server's reason is lost."""
    session.initialize()
    with pytest.raises(ProbeError, match="refusing to answer"):
        session.call("silent", timeout=1.0)


def test_list_tools_returns_the_page_including_its_cursor(session: McpSession) -> None:
    session.initialize()
    page = session.list_tools()

    assert page["nextCursor"] == "page-2"
    assert session.list_tools(page["nextCursor"])["tools"] == []
